import type { CareerVisualId } from "../../components/diagrams/CareerInterviewDiagrams";

export type TableData = { title: string; headers: string[]; rows: string[][] };
export type SectionData = { title: string; paragraphs?: string[]; bullets?: string[]; table?: TableData };
export type InterviewQuestion = { question: string; testing: string; short: string; deeper: string; example?: string; followup: string; mistake: string };
export type CodeExercise = { title: string; problem: string; reasoning: string; code: string; complexity: string; edge: string; followup: string; kind: "RUNNABLE PYTHON" | "RUNNABLE SQL / SQL EXAMPLE" };
export type DesignCase = { title: string; requirements: string; architecture: string; metrics: string; bottleneck: string; failures: string; tradeoffs: string; followup: string };
export type DebugScenario = { title: string; symptom: string; causes: string; evidence: string; action: string; fix: string; prevention: string };
export type PromptData = { question: string; framework: string; avoid: string };
export type CareerLesson = {
  opening: string[];
  objectives: string[];
  sections: SectionData[];
  visuals: CareerVisualId[];
  questions?: InterviewQuestion[];
  exercises?: CodeExercise[];
  cases?: DesignCase[];
  scenarios?: DebugScenario[];
  prompts?: PromptData[];
  links: Array<[string, string, string]>;
  summary: string[];
};

